/* Put Study Buddy on a phone: a web page cannot install an app by itself, so Settings gets a short guided card. */
(function(){
var LINK='https://claude.ai/artifact/Mg1ofXxuYQaYbqB14ZzXqQ';
function plat(){var u=navigator.userAgent||'';if(/iPhone|iPad|iPod/.test(u)||(/Macintosh/.test(u)&&navigator.maxTouchPoints>1))return'ios';if(/Android/.test(u))return'android';return'other'}
function toast(m){var t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.textContent=m;document.body.appendChild(t);setTimeout(function(){if(t.parentNode)t.parentNode.removeChild(t)},2600)}
var IOS='<ol class="ins"><li>Open the link in <b>Safari</b>.</li><li>Tap the <b>Share</b> button.</li><li>Tap <b>Add to Home Screen</b>, then <b>Add</b>.</li></ol>';
var AND='<ol class="ins"><li>Open the link in <b>Chrome</b>.</li><li>Tap the <b>⋮</b> menu.</li><li>Tap <b>Add to Home screen</b> (or <b>Install app</b>), then <b>Add</b>.</li></ol>';
function html(){var p=plat();
  var main=p==='ios'?'<b>iPhone or iPad</b>'+IOS:p==='android'?'<b>Android</b>'+AND:'';
  var other=p==='ios'?'<details><summary>On an Android phone</summary>'+AND+'</details>':p==='android'?'<details><summary>On an iPhone or iPad</summary>'+IOS+'</details>':'<details open><summary>On an iPhone or iPad</summary>'+IOS+'</details><details><summary>On an Android phone</summary>'+AND+'</details>';
  return'<h2>Put Study Buddy on a phone</h2><p class="sub" style="margin:2px 0 8px">An app cannot be installed for you automatically, but this takes about 20 seconds.</p>'+
  '<div class="row2"><button class="btn" onclick="sbInst.share()">Share link</button><button class="btn alt" onclick="sbInst.copy()">Copy link</button></div>'+
  '<div style="margin-top:12px">'+main+other+'</div>'+
  '<p class="sub" style="margin:10px 0 0;font-size:.85rem">Anything that asks Claude needs the person to be signed in to Claude. The Claude app is optional: the link also opens in the phone browser. <a href="https://claude.ai/download" target="_blank" rel="noopener" style="color:var(--accent)">Get the Claude app</a></p>'}
window.sbInst={
  share:function(){if(navigator.share){navigator.share({title:'Study Buddy',text:'Study Buddy: maths and exam practice',url:LINK}).catch(function(){})}else this.copy()},
  copy:function(){var done=function(){toast('Link copied.')};
    try{navigator.clipboard.writeText(LINK).then(done,function(){toast(LINK)})}catch(e){toast(LINK)}}
};
function place(){var rc=document.getElementById('roleCard');if(!rc||document.getElementById('instCard'))return;
  var c=document.createElement('div');c.className='card';c.id='instCard';c.innerHTML=html();
  var a=document.getElementById('pfCard')||rc;a.insertAdjacentElement('afterend',c)}
try{new MutationObserver(function(){try{place()}catch(e){}}).observe(document.body,{childList:true,subtree:true});place()}catch(e){}
})();
